(window.CONTENT_LOADED=window.CONTENT_LOADED||{})["usluga/dzierzawa-rolna"]={"h1Full":"Umowy dzierżawy rolnej: czas trwania, czynsz, wypowiedzenie i pierwokup dzierżawcy","topic":"Dzierżawa rolna","subtitle":"Dzierżawca nie płaci, chcesz sprzedać pole albo notariusz przysłał Ci zawiadomienie o sprzedaży ziemi, którą uprawiasz? Umowa dzierżawy gruntu rolnego na ponad rok powinna być pisemna; bez tej formy jest bezterminowa (art. 660 w zw. z art. 694 k.c.). Piszę i sprawdzam takie umowy, przygotowuję wypowiedzenia i prowadzę sprawy o czynsz i zwrot gruntu.","short":{"q":"Co powinna zawierać umowa dzierżawy gruntu rolnego?","a":"Musi wskazywać grunt oddany do używania i pobierania pożytków oraz czynsz (art. 693 § 1 k.c.). Warto dopisać rok dzierżawny (np. od 1.10 do 30.09), termin płatności czynszu i to, czy dzierżawca ponosi podatki (art. 699, 702, 704 k.c.). Aktu notarialnego kodeks nie wymaga (art. 660 w zw. z art. 694 k.c.).","facts":[["Forma","Pismo przy umowie na ponad rok, inaczej umowa jest bezterminowa (art. 660 w zw. z art. 694 k.c.)"],["Wypowiedzenie umowy bezterminowej","Rok naprzód, na koniec roku dzierżawnego, jeżeli umowa nie stanowi inaczej (art. 704 k.c.)"],["Zaległy czynsz","Zwłoka za 2 pełne okresy płatności, a gdy czynsz jest roczny, ponad 3 miesiące; potem 3 miesiące na zapłatę i wypowiedzenie bez terminu (art. 703 k.c.)"],["Sprzedaż ziemi","Nabywca wchodzi w dzierżawę. Nie wypowie jej, jeżeli zawarto ją na piśmie, z datą pewną (np. wzmianka notariusza, art. 81 § 2 k.c.), na czas oznaczony, a grunt wydano (art. 678 w zw. z art. 694 k.c.)"],["Pierwokup dzierżawcy","Umowa pisemna z datą pewną, wykonywana co najmniej 3 lata od tej daty, grunt w gospodarstwie rodzinnym dzierżawcy; miesiąc na decyzję od zawiadomienia (art. 3 u.k.u.r., art. 598 § 2 k.c.)"],["Szkoda po zwrocie gruntu","Roszczenie o pogorszenie gruntu przedawnia się po roku od zwrotu (art. 677 w zw. z art. 694 k.c.)"]]},"introHeading":"Co kodeks ustali za Ciebie, a co musisz wpisać do umowy","intro":"Dzierżawa to umowa, w której wydzierżawiający oddaje grunt do używania i pobierania pożytków (czyli do uprawy i zbioru plonów), a dzierżawca płaci umówiony czynsz (art. 693 § 1 k.c.). Czynsz może być w pieniądzu albo w części plonów (art. 693 § 2 k.c.). Czego przepisy o dzierżawie nie regulują, do tego stosuje się odpowiednio przepisy o najmie (art. 694 k.c.). Termin płatności czynszu kodeks uzupełni sam (art. 699 k.c.), ale roku dzierżawnego nie ustala, choć od jego końca liczy się wypowiedzenie (art. 704 k.c.).","whenTitle":"Czy to Twoja sytuacja","whenHeading":"Dzierżawca nie płaci, chcesz sprzedać pole albo umowa była „na słowo”","when":[{"b":"Dostałeś od notariusza zawiadomienie o sprzedaży ziemi, którą dzierżawisz.","t":"Jeżeli masz pierwokup, wykonujesz go w miesiąc od otrzymania zawiadomienia, w formie aktu notarialnego (art. 3 ust. 3 u.k.u.r., art. 597 § 2, art. 598 § 2, art. 158 k.c.)."},{"b":"Dzierżawca nie płaci czynszu za kolejne terminy.","t":"Wypowiedzenie bez terminu jest możliwe dopiero po uprzedzeniu dzierżawcy i 3 miesiącach na zapłatę (art. 703 k.c.)."},{"b":"Umowę zawarliście „na słowo” albo na kartce bez daty.","t":"Umowa na ponad rok bez pisma jest bezterminowa, a bez daty pewnej nie daje dzierżawcy pierwokupu (art. 660 w zw. z art. 694 k.c., art. 3 ust. 1 u.k.u.r.)."},{"b":"Chcesz sprzedać ziemię, na której gospodaruje dzierżawca.","t":"Kupujący przejmuje umowę, a gdy dzierżawca ma pierwokup, sprzedajesz warunkowo (art. 678 § 1 w zw. z art. 694, art. 597 § 1 k.c.)."},{"b":"Umowa się skończyła, a dzierżawca dalej uprawia pole.","t":"Jeżeli się na to godzisz, w razie wątpliwości umowa trwa dalej bez terminu (art. 674 w zw. z art. 694 k.c.). Jeżeli się nie godzisz, możesz żądać zwrotu gruntu (art. 705 k.c.)."}],"doForTitle":"Co przygotowuję dla właściciela ziemi i dla rolnika, który ją uprawia","doFor":["Piszę umowę dzierżawy albo aneks: czas trwania, czynsz, rok dzierżawny, podatki, przypadki wypowiedzenia.","Sprawdzam umowę, którą dostałeś do podpisu, i wypisuję zapisy działające tylko na korzyść drugiej strony.","Ustalam, czy data pewna leży w Twoim interesie, i jak ją nadać (art. 81 § 2 k.c.).","Przy sprzedaży dzierżawionej ziemi sprawdzam pierwokup dzierżawcy i uzgadniam z notariuszem umowę warunkową.","Przygotowuję uprzedzenie o zaległym czynszu i wypowiedzenie, potem pozew o czynsz, zwrot gruntu albo szkodę."],"lists":[{"eyebrow":"Zamiast wzoru z internetu","title":"Cztery zapisy, których wzór z internetu nie ustali za Ciebie","kind":"check","items":[{"b":"Rok dzierżawny","t":"od niego liczy się koniec wypowiedzenia (art. 704 k.c.) i czynsz za niepełny rok (art. 707 k.c.)."},{"b":"Termin płatności czynszu","t":"bez niego czynsz płaci się z dołu w terminie zwyczajowym, a bez zwyczaju półrocznie (art. 699 k.c.)."},{"b":"Podatki od gruntu","t":"jeżeli oprócz czynszu ponosi je dzierżawca, zapisz to; zwrot kwot zapłaconych za niego zabezpiecza ustawowe prawo zastawu (art. 702 k.c.)."},{"b":"Zasiewy przy zwrocie","t":"dzierżawca może żądać zwrotu nakładów na zasiewy pozostawione zgodnie z obowiązkiem, o ile sam nie dostał odpowiednich na początku (art. 706 k.c.)."}]}],"stepsHeading":"Od podpisu umowy do zwrotu pola: kolejne kroki","steps":["Przesyłasz umowę albo spisane ustalenia ustne. Odpiszę w 24 h roboczych, czy potrzebna jest nowa umowa, uprzedzenie o zaległym czynszu czy pozew, i dołączę ofertę z ceną i terminem.","Umowę podpisujecie na piśmie. Datę pewną nadajemy, jeżeli służy stronie, którą reprezentuję, bo wzmacnia ona pozycję dzierżawcy (art. 678 § 2 k.c., art. 3 ust. 1 u.k.u.r.).","Przy zaległości wysyłam uprzedzenie z 3 miesiącami na zapłatę, a po ich upływie wypowiedzenie. Wypowiedzenie to krok nieodwracalny: po doręczeniu nie odwołasz go jednostronnie (art. 61 § 1 k.c.).","Gdy dzierżawca nie płaci albo po końcu umowy nie oddaje gruntu, składam pozew o zapłatę albo o zwrot gruntu (art. 705 k.c.)."],"faq":[{"q":"Na ile lat najlepiej wydzierżawić ziemię?","a":"Kodeks nie wskazuje najlepszego okresu; umowa na ponad 30 lat staje się po ich upływie bezterminowa (art. 695 § 1 k.c.). Umowę na czas oznaczony wypowiesz tylko z przyczyn z umowy albo z ustawy, np. przy zaległym czynszu albo poddzierżawie bez Twojej zgody (art. 673 § 3 w zw. z art. 694, art. 698 § 2, art. 703 k.c.). Krótszy okres daje Ci więc szybszy powrót do gruntu."},{"q":"Jak wypowiedzieć dzierżawę gruntu rolnego – rok naprzód?","a":"Tak, jeżeli umowa jest bezterminowa i nie przewiduje innego terminu (art. 704 k.c.). Przykład (daty umowne): rok dzierżawny kończy się 30.09; wypowiedzenie doręczone 20.08.2026 r. kończy umowę 30.09.2027 r."},{"q":"Dzierżawca nie płaci – czy mogę rozwiązać umowę od razu?","a":"Nie od razu. Najpierw zwłoka musi objąć 2 pełne okresy płatności, a przy czynszu rocznym trwać ponad 3 miesiące. Potem uprzedzasz dzierżawcę i dajesz mu 3 miesiące na zapłatę. Dopiero po nich wypowiadasz umowę bez terminu (art. 703 k.c.)."},{"q":"Czy dzierżawca ma pierwokup, kiedy sprzedam ziemię?","a":"Tak, jeżeli spełnia 3 warunki. Umowa jest pisemna z datą pewną, wykonywana co najmniej 3 lata od tej daty, a grunt wchodzi w jego gospodarstwo rodzinne (prowadzone przez rolnika indywidualnego, do 300 ha użytków rolnych; art. 3 ust. 1, art. 5 ust. 1 u.k.u.r.). Sprzedaż bez warunku jest wtedy nieważna (art. 599 § 2 k.c.). Pierwokupu nie ma m.in. przy sprzedaży osobie bliskiej albo za zgodą Dyrektora Generalnego Krajowego Ośrodka Wsparcia Rolnictwa (art. 3 ust. 5 u.k.u.r.)."},{"q":"Czy umowa dzierżawy musi mieć datę pewną albo notariusza?","a":"Nie musi: przy umowie na ponad rok kodeks wymaga pisma, a aktu notarialnego nie (art. 660 w zw. z art. 694 k.c.). Datę pewną (skuteczną także wobec osób spoza umowy) uzyskasz np. przez wzmiankę notariusza albo wójta z datą na umowie (art. 81 § 1 i § 2 pkt 2 k.c.). Bez niej dzierżawca nie ma pierwokupu, a kupujący ziemię może wypowiedzieć dzierżawę (art. 3 ust. 1 u.k.u.r., art. 678 k.c.)."}],"law":{"asOf":"2026-10-10","items":[{"ref":"art. 693–707","act":"Ustawa z dnia 23 kwietnia 1964 r. – Kodeks cywilny","tj":"Dz.U. 2026 poz. 795","eli":"DU/1964/93","note":"Dzierżawa: czynsz, poddzierżawa, zaległość, wypowiedzenie, zwrot gruntu, zasiewy."},{"ref":"art. 660, 673, 674, 677, 678 w zw. z art. 694; art. 61, 81, 158, 597–599","act":"Ustawa z dnia 23 kwietnia 1964 r. – Kodeks cywilny","tj":"Dz.U. 2026 poz. 795","eli":"DU/1964/93","note":"Forma, wypowiedzenie, sprzedaż gruntu w czasie dzierżawy, data pewna, wykonanie pierwokupu."},{"ref":"art. 2a ust. 4, art. 3, art. 5","act":"Ustawa z dnia 11 kwietnia 2003 r. o kształtowaniu ustroju rolnego","tj":"Dz.U. 2026 poz. 941","eli":"DU/2003/592","note":"Pierwokup dzierżawcy, jego wyłączenia i gospodarstwo rodzinne."}]},"docs":["Umowa dzierżawy z aneksami albo opis ustaleń ustnych: od kiedy, na ile, jaki czynsz","Numery działek i numer księgi wieczystej, jeśli masz","Potwierdzenia wpłat czynszu albo lista zaległości z terminami płatności","Wezwania i wypowiedzenie z datą doręczenia, jeśli były","Zawiadomienie notariusza o sprzedaży albo projekt umowy sprzedaży ziemi, jeśli są"],"seeAlso":["bezumowne-korzystanie","obsluga-prawna-przedsiebiorstw-rolnych"],"cta":{"heading":"Dobra umowa dzierżawy chroni Cię, zanim pojawi się problem.","lead":"Napisz, czy wydzierżawiasz, czy dzierżawisz, i czego dotyczy problem: umowa, czynsz albo sprzedaż ziemi. W 24 h roboczych odpiszę, co trzeba zrobić, i prześlę ofertę z ceną i terminem; do jej akceptacji nic nie płacisz."}};
